import { Network } from "lucide-react";
import {
  useGetList,
  useGetMany,
  useTranslate,
  useCreatePath,
} from "ra-core";
import { Link } from "react-router";
import { Card } from "@/components/ui/card";

import type { Contact, Lead, Company } from "../types";
import { DashboardSectionHeader } from "./DashboardSectionHeader";

type LeadRank = {
  leadId: string | number | null;
  name: string;
  count: number;
};

export const BniAttribution = () => {
  const translate = useTranslate();
  const createPath = useCreatePath();

  const { data: bniContacts, total: bniContactTotal, isPending: contactsPending } =
    useGetList<Contact>("contacts", {
      pagination: { page: 1, perPage: 500 },
      sort: { field: "last_seen", order: "DESC" },
      filter: { is_bni: true },
    });

  const { total: bniLeadTotal, isPending: leadsPending } = useGetList<Lead>(
    "leads",
    {
      pagination: { page: 1, perPage: 1 },
      filter: { is_bni: true },
    },
  );

  const { total: bniCompanyTotal, isPending: companiesPending } =
    useGetList<Company>("companies", {
      pagination: { page: 1, perPage: 1 },
      filter: { is_bni: true },
    });

  const sourceLeadIds = Array.from(
    new Set(
      (bniContacts ?? [])
        .map((c) => c.source_lead_id)
        .filter((id): id is NonNullable<typeof id> => id != null),
    ),
  );

  const { data: sourceLeads, isPending: sourceLeadsPending } = useGetMany<Lead>(
    "leads",
    { ids: sourceLeadIds },
    { enabled: sourceLeadIds.length > 0 },
  );

  const isPending =
    contactsPending ||
    leadsPending ||
    companiesPending ||
    (sourceLeadIds.length > 0 && sourceLeadsPending);

  const leadNameById = new Map<string, string>();
  for (const lead of sourceLeads ?? []) {
    leadNameById.set(
      String(lead.id),
      `${lead.first_name ?? ""} ${lead.last_name ?? ""}`.trim() ||
        `#${lead.id}`,
    );
  }

  const counts = new Map<string, number>();
  let unattributed = 0;
  for (const contact of bniContacts ?? []) {
    if (contact.source_lead_id == null) {
      unattributed += 1;
      continue;
    }
    const key = String(contact.source_lead_id);
    counts.set(key, (counts.get(key) ?? 0) + 1);
  }

  const ranking: LeadRank[] = Array.from(counts.entries())
    .map(([leadId, count]) => ({
      leadId,
      name: leadNameById.get(leadId) ?? `#${leadId}`,
      count,
    }))
    .sort((a, b) => b.count - a.count);

  if (unattributed > 0) {
    ranking.push({
      leadId: null,
      name: translate("dashboard.bni.unattributed"),
      count: unattributed,
    });
  }

  const isEmpty = !isPending && !(bniContactTotal || bniLeadTotal || bniCompanyTotal);

  return (
    <div className="flex flex-col gap-4">
      <DashboardSectionHeader
        icon={<Network className="text-muted-foreground w-6 h-6" />}
        title={translate("dashboard.bni.title")}
        action={<span />}
      />

      {isPending ? (
        <p className="text-sm text-muted-foreground">…</p>
      ) : isEmpty ? (
        <p className="text-sm text-muted-foreground">
          {translate("dashboard.bni.empty")}
        </p>
      ) : (
        <Card className="p-4 space-y-4">
          <div className="grid grid-cols-3 gap-3 text-center">
            <Stat
              value={bniContactTotal ?? 0}
              label={translate("dashboard.bni.stranke")}
            />
            <Stat
              value={bniLeadTotal ?? 0}
              label={translate("dashboard.bni.leads")}
            />
            <Stat
              value={bniCompanyTotal ?? 0}
              label={translate("dashboard.bni.companies")}
            />
          </div>

          {ranking.length > 0 ? (
            <div className="space-y-2">
              <h3 className="text-sm font-medium text-muted-foreground">
                {translate("dashboard.bni.top_leads")}
              </h3>
              <ul className="divide-y rounded-md border">
                {ranking.slice(0, 8).map((row, index) => (
                  <li
                    key={row.leadId == null ? "none" : String(row.leadId)}
                    className="flex items-center justify-between gap-2 px-3 py-2 text-sm"
                  >
                    <span className="flex items-center gap-2 min-w-0">
                      <span className="text-muted-foreground w-5 shrink-0">
                        {index + 1}.
                      </span>
                      {row.leadId != null ? (
                        <Link
                          to={createPath({
                            resource: "leads",
                            type: "show",
                            id: row.leadId,
                          })}
                          className="truncate no-underline text-foreground hover:underline"
                        >
                          {row.name}
                        </Link>
                      ) : (
                        <span className="truncate text-muted-foreground">
                          {row.name}
                        </span>
                      )}
                    </span>
                    <span className="font-medium tabular-nums shrink-0">
                      {translate("dashboard.bni.stranke_count", {
                        smart_count: row.count,
                      })}
                    </span>
                  </li>
                ))}
              </ul>
            </div>
          ) : null}
        </Card>
      )}
    </div>
  );
};

const Stat = ({ value, label }: { value: number; label: string }) => (
  <div>
    <div className="text-2xl font-semibold tabular-nums">{value}</div>
    <div className="text-xs text-muted-foreground">{label}</div>
  </div>
);
