import {
  ListBase,
  useListContext,
  useTranslate,
  RecordContextProvider,
  useCreatePath,
} from "ra-core";
import { Link } from "react-router";
import { CreateButton } from "@/components/admin/create-button";
import { ListPagination } from "@/components/admin/list-pagination";
import { TopToolbar } from "../layout/TopToolbar";
import type { Lead } from "../types";

const LeadListActions = () => (
  <TopToolbar>
    <CreateButton />
  </TopToolbar>
);

export const LeadList = () => (
  <ListBase perPage={25} sort={{ field: "created_at", order: "DESC" }}>
    <div className="flex flex-col gap-4 p-4">
      <div className="flex justify-end">
        <LeadListActions />
      </div>
      <LeadListContent />
      <ListPagination />
    </div>
  </ListBase>
);

const LeadListContent = () => {
  const { data, isPending } = useListContext<Lead>();
  const translate = useTranslate();
  const createPath = useCreatePath();

  if (isPending) return null;
  if (!data?.length) {
    return (
      <p className="text-muted-foreground text-sm py-8">
        {translate("resources.leads.empty.title")}
      </p>
    );
  }

  return (
    <ul className="divide-y rounded-md border bg-background">
      {data.map((lead) => (
        <RecordContextProvider key={lead.id} value={lead}>
          <li>
            <Link
              to={createPath({ resource: "leads", type: "show", id: lead.id })}
              className="flex flex-wrap items-center justify-between gap-2 px-4 py-3 hover:bg-muted/40 no-underline text-foreground"
            >
              <div>
                <div className="font-medium">
                  {lead.first_name} {lead.last_name}
                </div>
                <div className="text-sm text-muted-foreground">
                  {lead.title ? `${lead.title} · ` : ""}
                  Tier {lead.tier}
                  {lead.is_bni ? " · BNI" : ""}
                  {lead.status ? ` · ${lead.status}` : ""}
                  {lead.converted_contact_id
                    ? ` · ${translate("resources.leads.converted_badge")}`
                    : ""}
                </div>
              </div>
              <span className="text-xs text-muted-foreground">
                {lead.address_form ?? ""}
              </span>
            </Link>
          </li>
        </RecordContextProvider>
      ))}
    </ul>
  );
};
