import {
  RecordContextProvider,
  ShowBase,
  useRecordContext,
  useTranslate,
} from "ra-core";
import { ReferenceField } from "@/components/admin/reference-field";
import { EditButton } from "@/components/admin/edit-button";
import { ConvertLeadButton } from "./ConvertLeadButton";
import type { Lead } from "../types";

export const LeadShow = () => (
  <ShowBase>
    <LeadShowContent />
  </ShowBase>
);

const LeadShowContent = () => {
  const record = useRecordContext<Lead>();
  const translate = useTranslate();
  if (!record) return null;

  return (
    <RecordContextProvider value={record}>
      <div className="p-4 max-w-3xl flex flex-col gap-6">
        <div className="flex flex-wrap items-start justify-between gap-3">
          <div>
            <h1 className="text-2xl font-semibold">
              {record.first_name} {record.last_name}
            </h1>
            <p className="text-muted-foreground text-sm">
              Tier {record.tier}
              {record.is_bni ? " · BNI" : ""}
              {record.status ? ` · ${record.status}` : ""}
              {record.title ? ` · ${record.title}` : ""}
            </p>
          </div>
          <div className="flex gap-2">
            <ConvertLeadButton />
            <EditButton />
          </div>
        </div>

        <dl className="grid gap-3 text-sm md:grid-cols-2">
          <Field
            label={translate("resources.leads.fields.company_id")}
            value={
              record.company_id != null ? (
                <ReferenceField
                  source="company_id"
                  reference="companies"
                  link="show"
                />
              ) : (
                "—"
              )
            }
          />
          <Field
            label={translate("resources.leads.fields.is_bni")}
            value={record.is_bni ? "BNI" : "—"}
          />
          <Field
            label={translate("resources.leads.fields.address_form")}
            value={record.address_form ?? "—"}
          />
          <Field
            label={translate("resources.leads.fields.name_pronunciation")}
            value={record.name_pronunciation ?? "—"}
          />
          <Field
            label={translate("resources.leads.fields.website")}
            value={record.website ?? "—"}
          />
          <Field
            label={translate("resources.leads.fields.linkedin_url")}
            value={record.linkedin_url ?? "—"}
          />
        </dl>

        <NoteBlock
          title={translate("resources.leads.fields.personal_notes")}
          text={record.personal_notes}
        />
        <NoteBlock
          title={translate("resources.leads.fields.niche_notes")}
          text={record.niche_notes}
        />
        <NoteBlock
          title={translate("resources.leads.fields.background")}
          text={record.background}
        />
      </div>
    </RecordContextProvider>
  );
};

const Field = ({
  label,
  value,
}: {
  label: string;
  value: React.ReactNode;
}) => (
  <div>
    <dt className="text-muted-foreground">{label}</dt>
    <dd className="font-medium">{value}</dd>
  </div>
);

const NoteBlock = ({ title, text }: { title: string; text?: string | null }) => {
  if (!text) return null;
  return (
    <section className="rounded-md border p-4">
      <h2 className="font-semibold mb-2">{title}</h2>
      <p className="text-sm whitespace-pre-wrap">{text}</p>
    </section>
  );
};
