import { useState } from "react";
import {
  useDataProvider,
  useNotify,
  useRecordContext,
  useRedirect,
  useRefresh,
  useTranslate,
  useGetIdentity,
} from "ra-core";
import { Button } from "@/components/ui/button";
import type { Contact, Lead } from "../types";

export const ConvertLeadButton = () => {
  const record = useRecordContext<Lead>();
  const translate = useTranslate();
  const notify = useNotify();
  const redirect = useRedirect();
  const refresh = useRefresh();
  const dataProvider = useDataProvider();
  const { identity } = useGetIdentity();
  const [busy, setBusy] = useState(false);

  if (!record) return null;
  if (record.converted_contact_id) {
    return (
      <Button
        variant="outline"
        onClick={() => redirect("show", "contacts", record.converted_contact_id!)}
      >
        {translate("resources.leads.action.open_stranka")}
      </Button>
    );
  }

  const handleConvert = async () => {
    if (!record.company_id) {
      notify("resources.leads.convert.company_required", { type: "warning" });
      return;
    }
    setBusy(true);
    try {
      const contactPayload: Partial<Contact> = {
        first_name: record.first_name,
        last_name: record.last_name,
        title: record.title ?? "",
        company_id: record.company_id,
        email_jsonb: record.email_jsonb ?? [],
        phone_jsonb: record.phone_jsonb ?? [],
        linkedin_url: record.linkedin_url ?? null,
        status: record.status ?? "warm",
        background: record.background ?? "",
        personal_notes: record.personal_notes ?? null,
        niche_notes: record.niche_notes ?? null,
        address_form: record.address_form ?? null,
        name_pronunciation: record.name_pronunciation ?? null,
        source_lead_id: record.id,
        is_bni: record.is_bni ?? false,
        tags: record.tags ?? [],
        sales_id: record.sales_id ?? (identity?.id as Contact["sales_id"]),
        gender: record.gender ?? "male",
        has_newsletter: false,
        first_seen: new Date().toISOString(),
        last_seen: new Date().toISOString(),
      };
      const { data: contact } = await dataProvider.create("contacts", {
        data: contactPayload,
      });
      await dataProvider.update("leads", {
        id: record.id,
        data: {
          converted_contact_id: contact.id,
          converted_at: new Date().toISOString(),
        },
        previousData: record,
      });
      notify("resources.leads.convert.success", { type: "info" });
      refresh();
      redirect("show", "contacts", contact.id);
    } catch (err) {
      notify(
        err instanceof Error ? err.message : "resources.leads.convert.error",
        { type: "error" },
      );
    } finally {
      setBusy(false);
    }
  };

  return (
    <Button onClick={() => void handleConvert()} disabled={busy}>
      {translate("resources.leads.action.convert_to_stranka")}
    </Button>
  );
};
