import { useCallback, useEffect, useRef, useState } from "react";
import { useTranslate } from "ra-core";
import { ArrowUp, Loader2, MessageSquarePlus, Square } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Textarea } from "@/components/ui/textarea";
import { Markdown } from "../misc/Markdown";
import {
  getConversation,
  listConversations,
  streamChat,
  streamConfirmWrite,
  toolLabel,
  type StoredMessage,
} from "./chatApi";
import type {
  ChatMessage,
  ConversationSummary,
  StreamEvent,
  WriteProposal,
} from "./types";

const ACTIVE_CHAT_KEY = "profiletter-chat-active-id";
const MAX_CHAT_HISTORY = 10;

function readActiveChatId(): string | null {
  try {
    return localStorage.getItem(ACTIVE_CHAT_KEY);
  } catch {
    return null;
  }
}

function writeActiveChatId(id: string | null) {
  try {
    if (id) localStorage.setItem(ACTIVE_CHAT_KEY, id);
    else localStorage.removeItem(ACTIVE_CHAT_KEY);
  } catch {
    // ignore quota / private mode
  }
}

function messagesFromStore(rows: StoredMessage[]): ChatMessage[] {
  const out: ChatMessage[] = [];
  for (const row of rows) {
    if (row.role === "USER") {
      out.push({
        id: row.id,
        role: "user",
        content: row.content,
        status: "complete",
      });
      continue;
    }
    if (row.role === "TOOL") {
      const last = out.at(-1);
      if (!last || last.role !== "assistant" || last.content) {
        out.push({
          id: `tools-${row.id}`,
          role: "assistant",
          content: "",
          status: "complete",
          toolCalls: [],
        });
      }
      const holder = out.at(-1);
      if (!holder) continue;
      holder.toolCalls = [
        ...(holder.toolCalls ?? []),
        {
          id: row.id,
          name: row.toolName ?? "tool",
          status: "complete",
          label: toolLabel(row.toolName ?? "tool"),
        },
      ];
      continue;
    }
    if (row.role === "ASSISTANT") {
      const last = out.at(-1);
      if (last?.role === "assistant" && !last.content) {
        last.id = row.id;
        last.content = row.content;
      } else {
        out.push({
          id: row.id,
          role: "assistant",
          content: row.content,
          status: "complete",
        });
      }
    }
  }
  return out;
}

export const ChatPage = () => {
  const translate = useTranslate();
  const [conversations, setConversations] = useState<ConversationSummary[]>([]);
  // Hydrate from localStorage so the first persist effect does not wipe the id.
  const [activeId, setActiveId] = useState<string | null>(() =>
    readActiveChatId(),
  );
  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [input, setInput] = useState("");
  const [isStreaming, setIsStreaming] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [loadingHistory, setLoadingHistory] = useState(
    () => Boolean(readActiveChatId()),
  );
  const abortRef = useRef<AbortController | null>(null);
  const historyRequestRef = useRef(0);
  const endRef = useRef<HTMLDivElement>(null);
  const textareaRef = useRef<HTMLTextAreaElement>(null);

  const refreshConversations = useCallback(async () => {
    try {
      const { items } = await listConversations();
      const limited = items.slice(0, MAX_CHAT_HISTORY);
      setConversations(limited);
      return limited;
    } catch {
      // API may be offline during local CRM-only work
      return [] as ConversationSummary[];
    }
  }, []);

  useEffect(() => {
    endRef.current?.scrollIntoView({ behavior: "smooth" });
  }, [messages]);

  useEffect(() => {
    writeActiveChatId(activeId);
  }, [activeId]);

  const startNewChat = () => {
    abortRef.current?.abort();
    historyRequestRef.current += 1;
    setActiveId(null);
    writeActiveChatId(null);
    setMessages([]);
    setInput("");
    setError(null);
    setLoadingHistory(false);
  };

  const openConversation = useCallback(
    async (id: string, opts?: { force?: boolean }) => {
      if (!opts?.force && id === activeId && messages.length > 0) return;
      abortRef.current?.abort();
      const requestId = historyRequestRef.current + 1;
      historyRequestRef.current = requestId;
      setActiveId(id);
      writeActiveChatId(id);
      setMessages([]);
      setError(null);
      setInput("");
      setLoadingHistory(true);
      try {
        const { conversation } = await getConversation(id);
        if (historyRequestRef.current !== requestId) return;
        setMessages(messagesFromStore(conversation.messages));
      } catch (err) {
        if (historyRequestRef.current !== requestId) return;
        writeActiveChatId(null);
        setActiveId(null);
        setError(
          err instanceof Error
            ? err.message
            : translate("crm.chat.api_unreachable"),
        );
      } finally {
        if (historyRequestRef.current === requestId) setLoadingHistory(false);
      }
    },
    [activeId, messages.length, translate],
  );

  // Restore the last open chat when navigating back to /chat.
  useEffect(() => {
    let cancelled = false;
    void (async () => {
      const saved = readActiveChatId();
      let items: ConversationSummary[] = [];
      try {
        items = await refreshConversations();
      } catch {
        items = [];
      }
      if (cancelled) return;

      if (!saved) {
        setLoadingHistory(false);
        return;
      }

      // Only drop the saved id when the list loaded and the chat is gone
      // (archived). If the list is empty due to a transient API error, keep it.
      if (items.length > 0 && !items.some((item) => item.id === saved)) {
        writeActiveChatId(null);
        setActiveId(null);
        setLoadingHistory(false);
        return;
      }

      const requestId = historyRequestRef.current + 1;
      historyRequestRef.current = requestId;
      setActiveId(saved);
      setLoadingHistory(true);
      try {
        const { conversation } = await getConversation(saved);
        if (cancelled || historyRequestRef.current !== requestId) return;
        setMessages(messagesFromStore(conversation.messages));
      } catch (err) {
        if (cancelled || historyRequestRef.current !== requestId) return;
        // Keep saved id on network errors so a later visit can retry.
        setError(
          err instanceof Error
            ? err.message
            : translate("crm.chat.api_unreachable"),
        );
      } finally {
        if (!cancelled && historyRequestRef.current === requestId) {
          setLoadingHistory(false);
        }
      }
    })();
    return () => {
      cancelled = true;
    };
  }, [refreshConversations, translate]);

  const stopGeneration = () => {
    abortRef.current?.abort();
    abortRef.current = null;
    setIsStreaming(false);
    setMessages((prev) =>
      prev.map((m) =>
        m.status === "streaming" ? { ...m, status: "complete" } : m,
      ),
    );
  };

  const applyStreamEvent = (
    assistantId: string,
    event: StreamEvent,
    onMeta?: (conversationId: string) => void,
  ) => {
    if (event.type === "meta") {
      onMeta?.(event.conversationId);
      setActiveId(event.conversationId);
      return;
    }
    if (event.type === "text_delta") {
      setMessages((prev) =>
        prev.map((m) =>
          m.id === assistantId
            ? {
                ...m,
                content: m.content + event.text,
                status: "streaming",
              }
            : m,
        ),
      );
      return;
    }
    if (event.type === "tool_call") {
      setMessages((prev) =>
        prev.map((m) =>
          m.id === assistantId
            ? {
                ...m,
                toolCalls: [
                  ...(m.toolCalls ?? []),
                  {
                    id: `${event.name}-${Date.now()}`,
                    name: event.name,
                    status: "running",
                    label: toolLabel(event.name),
                  },
                ],
              }
            : m,
        ),
      );
      return;
    }
    if (event.type === "write_proposal") {
      const proposal: WriteProposal = {
        id: event.id,
        name: event.name,
        input: event.input,
        summary: event.summary,
        status: "pending",
      };
      setMessages((prev) =>
        prev.map((m) => {
          if (m.id !== assistantId) return m;
          const existing = m.writeProposals ?? [];
          if (existing.some((p) => p.id === proposal.id)) return m;
          return { ...m, writeProposals: [...existing, proposal] };
        }),
      );
      return;
    }
    if (event.type === "tool_result") {
      setMessages((prev) =>
        prev.map((m) => {
          if (m.id !== assistantId) return m;
          const tools = [...(m.toolCalls ?? [])];
          const result = event.result as {
            ok?: boolean;
            needs_confirmation?: boolean;
            proposalId?: string;
            proposal?: unknown;
            summary?: string;
          } | null;
          for (let i = tools.length - 1; i >= 0; i -= 1) {
            const t = tools[i];
            if (t && t.name === event.name && t.status === "running") {
              const ok = result?.needs_confirmation
                ? true
                : typeof result === "object" && result && "ok" in result
                  ? Boolean(result.ok)
                  : true;
              tools[i] = {
                ...t,
                status: ok ? "complete" : "error",
              };
              break;
            }
          }
          let writeProposals = m.writeProposals ?? [];
          if (result?.needs_confirmation) {
            const proposalId =
              result.proposalId ?? `${event.name}-${Date.now()}`;
            if (!writeProposals.some((p) => p.id === proposalId)) {
              writeProposals = [
                ...writeProposals,
                {
                  id: proposalId,
                  name: event.name,
                  input: result.proposal ?? {},
                  summary:
                    result.summary ??
                    `${toolLabel(event.name)} — potrdi shranjevanje`,
                  status: "pending",
                },
              ];
            }
          }
          return { ...m, toolCalls: tools, writeProposals };
        }),
      );
      return;
    }
    if (event.type === "done") {
      setMessages((prev) =>
        prev.map((m) =>
          m.id === assistantId
            ? {
                ...m,
                content: event.assistantText || m.content,
                status: "complete",
              }
            : m,
        ),
      );
      return;
    }
    if (event.type === "error") {
      setError(event.message);
      setMessages((prev) =>
        prev.map((m) =>
          m.id === assistantId
            ? {
                ...m,
                status: "error",
                content: m.content || translate("crm.chat.unavailable"),
              }
            : m,
        ),
      );
    }
  };

  const sendMessage = async (raw?: string) => {
    const content = (raw ?? input).trim();
    if (!content || isStreaming) return;

    setError(null);
    setInput("");
    setIsStreaming(true);

    const assistantId = `assistant-${Date.now()}`;
    setMessages((prev) => [
      ...prev,
      {
        id: `user-${Date.now()}`,
        role: "user",
        content,
        status: "complete",
      },
      {
        id: assistantId,
        role: "assistant",
        content: "",
        status: "streaming",
        toolCalls: [],
        writeProposals: [],
      },
    ]);

    const controller = new AbortController();
    abortRef.current = controller;
    let conversationId = activeId;

    try {
      await streamChat({
        conversationId: conversationId ?? undefined,
        message: content,
        signal: controller.signal,
        onEvent: (event) => {
          applyStreamEvent(assistantId, event, (id) => {
            conversationId = id;
          });
        },
      });
      await refreshConversations();
    } catch (err) {
      if (controller.signal.aborted) return;
      setError(
        err instanceof Error
          ? err.message
          : translate("crm.chat.api_unreachable"),
      );
      const message =
        err instanceof Error ? err.message : translate("crm.chat.api_unreachable");
      setMessages((prev) =>
        prev.map((m) =>
          m.id === assistantId
            ? {
                ...m,
                status: "error",
                content: m.content || message,
              }
            : m,
        ),
      );
    } finally {
      setIsStreaming(false);
      abortRef.current = null;
      textareaRef.current?.focus();
    }
  };

  const cancelWriteProposal = (messageId: string, proposalId: string) => {
    setMessages((prev) =>
      prev.map((m) =>
        m.id === messageId
          ? {
              ...m,
              writeProposals: (m.writeProposals ?? []).map((p) =>
                p.id === proposalId ? { ...p, status: "cancelled" } : p,
              ),
            }
          : m,
      ),
    );
  };

  const confirmWriteProposal = async (
    messageId: string,
    proposal: WriteProposal,
  ) => {
    if (!activeId || isStreaming || proposal.status !== "pending") return;

    setError(null);
    setIsStreaming(true);
    setMessages((prev) =>
      prev.map((m) =>
        m.id === messageId
          ? {
              ...m,
              writeProposals: (m.writeProposals ?? []).map((p) =>
                p.id === proposal.id ? { ...p, status: "confirmed" } : p,
              ),
            }
          : m,
      ),
    );

    const assistantId = `assistant-confirm-${Date.now()}`;
    setMessages((prev) => [
      ...prev,
      {
        id: `user-confirm-${Date.now()}`,
        role: "user",
        content: translate("crm.chat.write_confirm_user"),
        status: "complete",
      },
      {
        id: assistantId,
        role: "assistant",
        content: "",
        status: "streaming",
        toolCalls: [],
        writeProposals: [],
      },
    ]);

    const controller = new AbortController();
    abortRef.current = controller;

    try {
      await streamConfirmWrite({
        conversationId: activeId,
        toolName: proposal.name,
        toolInput: proposal.input,
        proposalId: proposal.id,
        signal: controller.signal,
        onEvent: (event) => applyStreamEvent(assistantId, event),
      });
      await refreshConversations();
    } catch (err) {
      if (controller.signal.aborted) return;
      const message =
        err instanceof Error ? err.message : translate("crm.chat.api_unreachable");
      setError(message);
      setMessages((prev) =>
        prev.map((m) => {
          if (m.id === messageId) {
            return {
              ...m,
              writeProposals: (m.writeProposals ?? []).map((p) =>
                p.id === proposal.id
                  ? { ...p, status: "error", error: message }
                  : p,
              ),
            };
          }
          if (m.id === assistantId) {
            return {
              ...m,
              status: "error",
              content: m.content || message,
            };
          }
          return m;
        }),
      );
    } finally {
      setIsStreaming(false);
      abortRef.current = null;
      textareaRef.current?.focus();
    }
  };

  const suggestions = [
    translate("crm.chat.suggestions.active_stranke"),
    translate("crm.chat.suggestions.leads_followup"),
    translate("crm.chat.suggestions.recent_activity"),
    translate("crm.chat.suggestions.no_next_step"),
  ];

  const pendingProposals = messages.flatMap((m) =>
    (m.writeProposals ?? [])
      .filter((p) => p.status === "pending")
      .map((p) => ({ messageId: m.id, proposal: p })),
  );

  return (
    <div className="flex min-h-0 w-full flex-1 bg-background">
      <aside className="hidden w-64 shrink-0 flex-col border-r bg-muted/20 md:flex">
        <div className="p-3">
          <Button
            type="button"
            variant="outline"
            className="w-full justify-start gap-2"
            onClick={startNewChat}
          >
            <MessageSquarePlus className="size-4" />
            {translate("crm.chat.new_chat")}
          </Button>
        </div>
        <nav className="flex-1 space-y-1 overflow-y-auto px-2 pb-3">
          {conversations.map((c) => (
            <button
              key={c.id}
              type="button"
              onClick={() => void openConversation(c.id)}
              className={`w-full truncate rounded-lg px-2.5 py-2 text-left text-sm transition ${
                activeId === c.id
                  ? "bg-muted font-medium"
                  : "text-muted-foreground hover:bg-muted/70"
              }`}
            >
              {c.title}
            </button>
          ))}
        </nav>
      </aside>

      <section className="flex min-w-0 flex-1 flex-col">
        <div className="flex items-center justify-between border-b px-4 py-3">
          <div>
            <h2 className="text-base font-semibold">
              {translate("crm.chat.title")}
            </h2>
            <p className="text-xs text-muted-foreground">
              {translate("crm.chat.ask_subtitle")}
            </p>
          </div>
          <Button
            type="button"
            variant="ghost"
            size="sm"
            className="md:hidden"
            onClick={startNewChat}
          >
            {translate("crm.chat.new")}
          </Button>
        </div>

        {error && (
          <div className="border-b border-destructive/30 bg-destructive/10 px-4 py-2 text-center text-sm text-destructive">
            {error}
          </div>
        )}

        <div className="flex min-h-0 flex-1 flex-col overflow-y-auto px-6 py-6">
          {loadingHistory ? (
            <div className="flex flex-1 items-center justify-center text-sm text-muted-foreground">
              <Loader2 className="mr-2 size-4 animate-spin" />
              {translate("crm.common.loading")}
            </div>
          ) : messages.length === 0 ? (
            <div className="mx-auto flex w-full max-w-3xl flex-1 flex-col items-center justify-center text-center">
              <div
                className="mb-6 flex size-12 items-center justify-center rounded-full border-2"
                style={{ borderColor: "var(--brand)", color: "var(--brand)" }}
                aria-hidden
              >
                <span className="text-2xl leading-none">∗</span>
              </div>
              <h3 className="text-2xl font-semibold tracking-tight">
                {translate("crm.chat.empty_title")}
              </h3>
              <p className="mt-2 text-muted-foreground">
                {translate("crm.chat.empty_subtitle")}
              </p>
              <div className="mt-8 grid w-full gap-3 sm:grid-cols-2">
                {suggestions.map((text) => (
                  <button
                    key={text}
                    type="button"
                    onClick={() => void sendMessage(text)}
                    className="rounded-xl border bg-card px-4 py-3 text-left text-sm transition hover:border-[var(--brand)] hover:bg-[var(--brand)]/5"
                  >
                    {text}
                  </button>
                ))}
              </div>
            </div>
          ) : (
            <div className="mx-auto flex w-full max-w-3xl flex-col gap-6">
              {messages.map((message) => (
                <div
                  key={message.id}
                  className={`flex ${message.role === "user" ? "justify-end" : "justify-start"}`}
                >
                  <div
                    className={
                      message.role === "user"
                        ? "ml-auto w-fit min-w-[min(100%,22rem)] max-w-full"
                        : "w-full"
                    }
                  >
                    {message.toolCalls && message.toolCalls.length > 0 && (
                      <div className="mb-2 flex flex-wrap gap-2">
                        {message.toolCalls.map((tool) => (
                          <span
                            key={tool.id}
                            className="inline-flex items-center gap-1.5 rounded-full border bg-muted/60 px-2.5 py-1 text-xs text-muted-foreground"
                          >
                            {tool.status === "running" && (
                              <Loader2 className="size-3 animate-spin" />
                            )}
                            {tool.label ?? tool.name}
                          </span>
                        ))}
                      </div>
                    )}
                    {message.writeProposals &&
                      message.writeProposals.length > 0 && (
                        <div className="mb-3 space-y-2">
                          {message.writeProposals.map((proposal) => (
                            <div
                              key={proposal.id}
                              className="rounded-xl border border-[var(--brand)]/30 bg-[var(--brand)]/5 p-3"
                            >
                              <p className="text-xs font-medium uppercase tracking-wide text-muted-foreground">
                                {translate("crm.chat.write_proposal_title")}
                              </p>
                              <p className="mt-1 whitespace-pre-line text-sm">
                                {proposal.summary}
                              </p>
                              {proposal.status === "pending" && (
                                <div className="mt-3 flex gap-2">
                                  <Button
                                    type="button"
                                    size="sm"
                                    disabled={isStreaming}
                                    onClick={() =>
                                      void confirmWriteProposal(
                                        message.id,
                                        proposal,
                                      )
                                    }
                                  >
                                    {translate("crm.chat.write_confirm")}
                                  </Button>
                                  <Button
                                    type="button"
                                    size="sm"
                                    variant="outline"
                                    disabled={isStreaming}
                                    onClick={() =>
                                      cancelWriteProposal(
                                        message.id,
                                        proposal.id,
                                      )
                                    }
                                  >
                                    {translate("crm.chat.write_cancel")}
                                  </Button>
                                </div>
                              )}
                              {proposal.status === "confirmed" && (
                                <p className="mt-2 text-xs text-muted-foreground">
                                  {translate("crm.chat.write_confirmed")}
                                </p>
                              )}
                              {proposal.status === "cancelled" && (
                                <p className="mt-2 text-xs text-muted-foreground">
                                  {translate("crm.chat.write_cancelled")}
                                </p>
                              )}
                              {proposal.status === "error" && (
                                <p className="mt-2 text-xs text-destructive">
                                  {proposal.error ||
                                    translate("crm.chat.write_failed")}
                                </p>
                              )}
                            </div>
                          ))}
                        </div>
                      )}
                    <div
                      className={`rounded-2xl px-4 py-3 leading-relaxed ${
                        message.role === "user"
                          ? "bg-primary text-primary-foreground"
                          : "bg-transparent"
                      }`}
                    >
                      {message.role === "user" ? (
                        <p className="whitespace-pre-wrap text-[15px]">
                          {message.content}
                        </p>
                      ) : message.content ? (
                        <Markdown>{message.content}</Markdown>
                      ) : (
                        <span className="inline-flex items-center gap-2 text-sm text-muted-foreground">
                          <Loader2 className="size-3.5 animate-spin" />
                          {translate("crm.common.loading")}
                        </span>
                      )}
                    </div>
                  </div>
                </div>
              ))}
              <div ref={endRef} />
            </div>
          )}
        </div>

        <div className="px-6 pb-4 pt-2">
          {pendingProposals.length > 0 && (
            <div className="mx-auto mb-3 w-full max-w-3xl space-y-2">
              {pendingProposals.map(({ messageId, proposal }) => (
                <div
                  key={proposal.id}
                  className="rounded-xl border-2 border-[var(--brand)] bg-[var(--brand)]/10 p-3 shadow-sm"
                >
                  <p className="text-xs font-semibold uppercase tracking-wide text-[var(--brand)]">
                    {translate("crm.chat.write_proposal_title")}
                  </p>
                  <p className="mt-1 whitespace-pre-line text-sm font-medium">
                    {proposal.summary}
                  </p>
                  <div className="mt-3 flex gap-2">
                    <Button
                      type="button"
                      size="sm"
                      disabled={isStreaming}
                      onClick={() =>
                        void confirmWriteProposal(messageId, proposal)
                      }
                    >
                      {translate("crm.chat.write_confirm")}
                    </Button>
                    <Button
                      type="button"
                      size="sm"
                      variant="outline"
                      disabled={isStreaming}
                      onClick={() =>
                        cancelWriteProposal(messageId, proposal.id)
                      }
                    >
                      {translate("crm.chat.write_cancel")}
                    </Button>
                  </div>
                </div>
              ))}
            </div>
          )}
          <form
            className="mx-auto flex w-full max-w-3xl items-end gap-2 rounded-2xl border bg-card p-2"
            onSubmit={(e) => {
              e.preventDefault();
              void sendMessage();
            }}
          >
            <Textarea
              ref={textareaRef}
              value={input}
              onChange={(e) => setInput(e.target.value)}
              onKeyDown={(e) => {
                if (e.key === "Enter" && !e.shiftKey) {
                  e.preventDefault();
                  if (!isStreaming && input.trim()) void sendMessage();
                }
              }}
              placeholder={translate("crm.chat.placeholder")}
              rows={1}
              className="min-h-12 max-h-40 flex-1 resize-none border-0 bg-transparent shadow-none focus-visible:ring-0"
            />
            {isStreaming ? (
              <Button
                type="button"
                size="icon"
                variant="outline"
                onClick={stopGeneration}
                aria-label={translate("crm.chat.stop")}
              >
                <Square className="size-4 fill-current" />
              </Button>
            ) : (
              <Button
                type="submit"
                size="icon"
                disabled={!input.trim()}
                aria-label={translate("crm.chat.send")}
              >
                <ArrowUp className="size-4" />
              </Button>
            )}
          </form>
          <p className="mt-2 text-center text-xs text-muted-foreground">
            {translate("crm.chat.disclaimer")}
          </p>
        </div>
      </section>
    </div>
  );
};

ChatPage.path = "/chat";
