async function readSseStream(
  res: Response,
  onEvent: (event: StreamEvent) => void,
) {
  if (!res.ok || !res.body) {
    let message = `Chat failed (${res.status})`;
    try {
      const body = (await res.json()) as { error?: { message?: string } };
      if (body.error?.message) message = body.error.message;
    } catch {
      // ignore
    }
    throw new Error(message);
  }

  const reader = res.body.getReader();
  const decoder = new TextDecoder();
  let buffer = "";
  let eventName = "message";

  while (true) {
    const { value, done } = await reader.read();
    if (done) break;
    buffer += decoder.decode(value, { stream: true });
    const parts = buffer.split("\n");
    buffer = parts.pop() ?? "";

    for (const line of parts) {
      if (line.startsWith("event:")) {
        eventName = line.slice(6).trim();
        continue;
      }
      if (!line.startsWith("data:")) continue;
      const raw = line.slice(5).trim();
      if (!raw) continue;
      try {
        const parsed = JSON.parse(raw) as StreamEvent | Record<string, unknown>;
        if (eventName === "meta" && "conversationId" in parsed) {
          onEvent({
            type: "meta",
            conversationId: String(parsed.conversationId),
          });
        } else if (
          typeof parsed === "object" &&
          parsed &&
          "type" in parsed &&
          typeof (parsed as { type?: unknown }).type === "string"
        ) {
          onEvent(parsed as StreamEvent);
        } else if (eventName !== "message") {
          onEvent({ type: eventName, ...parsed } as StreamEvent);
        }
      } catch {
        // ignore malformed chunk
      }
      eventName = "message";
    }
  }
}

export async function streamChat(input: {
  conversationId?: string;
  message: string;
  signal?: AbortSignal;
  onEvent: (event: StreamEvent) => void;
}) {
  const token = await getAccessToken();
  const res = await fetch(`${API_URL}/chat`, {
    method: "POST",
    headers: {
      "Content-Type": "application/json",
      ...(token ? { Authorization: `Bearer ${token}` } : {}),
    },
    body: JSON.stringify({
      conversationId: input.conversationId,
      message: input.message,
    }),
    signal: input.signal,
  });
  await readSseStream(res, input.onEvent);
}

export async function streamConfirmWrite(input: {
  conversationId: string;
  toolName: string;
  toolInput: unknown;
  proposalId?: string;
  signal?: AbortSignal;
  onEvent: (event: StreamEvent) => void;
}) {
  const token = await getAccessToken();
  const res = await fetch(`${API_URL}/chat/confirm-write`, {
    method: "POST",
    headers: {
      "Content-Type": "application/json",
      ...(token ? { Authorization: `Bearer ${token}` } : {}),
    },
    body: JSON.stringify({
      conversationId: input.conversationId,
      toolName: input.toolName,
      input: input.toolInput,
      proposalId: input.proposalId,
    }),
    signal: input.signal,
  });
  await readSseStream(res, input.onEvent);
}
